export interface Review {
  id: string;
  productId: string;
  reviewerId: string;
  comment: string;
  score: number;
}

export class ReviewLedger {
  private readonly reviews: Review[];

  constructor(initial: readonly Review[] = []) {
    this.reviews = initial.map(review => ({ ...review }));
  }

  add(review: Review): Review {
    if (
      review.id.trim() === '' || review.productId.trim() === '' ||
      review.reviewerId.trim() === '' || review.comment.trim() === '' ||
      !Number.isInteger(review.score) || review.score < 1 || review.score > 5
    ) {
      throw new TypeError('Invalid review');
    }
    if (this.reviews.some(item => item.id === review.id.trim())) {
      throw new RangeError('Duplicate review ID');
    }
    const stored: Review = {
      ...review,
      id: review.id.trim(),
      productId: review.productId.trim(),
      reviewerId: review.reviewerId.trim(),
      comment: review.comment.trim(),
    };
    this.reviews.push(stored);
    return stored;
  }

  forProduct(productId: string): Review[] {
    return this.reviews.filter(review => review.productId === productId).map(review => ({ ...review }));
  }
}
