import { ReviewLedger, type Review } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throwsNamed(fn: () => unknown, name: 'TypeError' | 'RangeError'): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof Error && error.name === name) return;
    throw new Error(`expected ${name}`);
  }
  throw new Error(`expected ${name}`);
}

const initial: Review[] = [
  { id: 'r1', productId: 'p1', reviewerId: 'u1', comment: 'first', score: 3 },
];
const ledger = new ReviewLedger(initial);
initial[0].comment = 'mutated outside';
initial.push({ id: 'external', productId: 'p1', reviewerId: 'u2', comment: 'outside', score: 4 });
equal(ledger.forProduct('p1'), [{ id: 'r1', productId: 'p1', reviewerId: 'u1', comment: 'first', score: 3 }], 'constructor defensively copies');

const input: Review = { id: ' r2 ', productId: ' p1 ', reviewerId: '\tu2 ', comment: ' useful review\n', score: 1 };
const inputSnapshot = JSON.stringify(input);
const added = ledger.add(input);
equal(added, { id: 'r2', productId: 'p1', reviewerId: 'u2', comment: 'useful review', score: 1 }, 'add trims stored strings');
assert(JSON.stringify(input) === inputSnapshot, 'add must not mutate argument');
added.comment = 'changed returned object';
equal(ledger.forProduct('p1').map(review => review.comment), ['first', 'useful review'], 'add return does not expose internal object');

const firstRead = ledger.forProduct('p1');
const secondRead = ledger.forProduct('p1');
assert(firstRead[0] !== secondRead[0] && firstRead[1] !== secondRead[1], 'each query returns new review objects');
firstRead[0].comment = 'changed query result';
equal(ledger.forProduct('p1')[0].comment, 'first', 'query result does not expose internal object');
equal(ledger.forProduct(' p1 '), [], 'product ID match is exact');
equal(ledger.forProduct('missing'), [], 'missing product');

const maxScore = ledger.add({ id: 'r5', productId: 'p2', reviewerId: 'u5', comment: 'five', score: 5 });
equal(maxScore.score, 5, 'upper score boundary');
equal(ledger.forProduct('p2').map(review => review.id), ['r5'], 'product lookup and insertion order');

for (const invalid of [
  { id: ' ', productId: 'p', reviewerId: 'u', comment: 'c', score: 3 },
  { id: 'x1', productId: '\t', reviewerId: 'u', comment: 'c', score: 3 },
  { id: 'x2', productId: 'p', reviewerId: '', comment: 'c', score: 3 },
  { id: 'x3', productId: 'p', reviewerId: 'u', comment: '\n', score: 3 },
  { id: 'x4', productId: 'p', reviewerId: 'u', comment: 'c', score: 0 },
  { id: 'x5', productId: 'p', reviewerId: 'u', comment: 'c', score: 6 },
  { id: 'x6', productId: 'p', reviewerId: 'u', comment: 'c', score: 2.5 },
] as Review[]) {
  throwsNamed(() => ledger.add(invalid), 'TypeError');
}
throwsNamed(() => ledger.add({ id: ' r2 ', productId: 'other', reviewerId: 'u', comment: 'duplicate', score: 4 }), 'RangeError');
equal(ledger.forProduct('p1').map(review => review.id), ['r1', 'r2'], 'failed additions do not change ledger');

